"""Display-only consistency gate for the 1-minute spherical target diagnostic.

Do not convert 'not verified' into 'physically impossible'.  A plotted twilight
minute must have a positive illumination witness at that same minute; otherwise
it is an empty/unknown point, never a colored light interval.
"""
from datetime import datetime

def gate_dynamic_curve(curve, times, fractions, target_count=0, profile_available=False):
    if not isinstance(curve, dict):
        return curve
    # ISO timestamps are generated by the same event_dt + integer-minute loop.
    evidence = {}
    for t, f in zip(times or [], fractions or []):
        try:
            evidence[datetime.fromisoformat(t).replace(second=0, microsecond=0)] = max(0.0, min(1.0, float(f)))
        except (TypeError, ValueError, OverflowError):
            continue
    positive = 0
    unresolved = 0
    for point in curve.get('samples', []):
        dt = point.get('datetime')
        key = dt.replace(second=0, microsecond=0) if isinstance(dt, datetime) else None
        frac = evidence.get(key)
        # Do not nearest-neighbor fill missing minutes; no extrapolation.
        verified = frac is not None and frac > 0.0
        if verified and point.get('geometry_valid'):
            point['tintable_cloud_area'] = round(float(point.get('tintable_cloud_area') or 0.0)*frac, 6)
            point['brightness'] = round(float(point.get('brightness') or 0.0)*frac, 2)
            positive += 1
        else:
            if frac is None or (not profile_available):
                unresolved += 1
            point['geometry_valid'] = False
            point['tintable_cloud_area'] = 0.0
            point['brightness'] = 0.0
        point['target_light_verified'] = bool(verified)
        point['target_light_fraction'] = frac
    valid = [p for p in curve.get('samples', []) if p.get('geometry_valid')]
    curve['peak'] = max(valid, key=lambda p:(p.get('tintable_cloud_area',0),p.get('brightness',0))) if valid else None
    peak_b = max((float(p.get('brightness') or 0) for p in valid), default=0)
    for point in curve.get('samples', []):
        point['relative_brightness'] = round(100*float(point.get('brightness') or 0)/peak_b,1) if peak_b else 0.0
    curve['geometry_gate_diagnostic'] = {
        'mode':'one_minute_exact_timestamp', 'target_count':target_count,
        'profile_available':profile_available, 'positive_plot_minutes':positive,
        'unresolved_plot_minutes':unresolved,
        'evidence_minutes':len(evidence),
        'caveat':'No witness does not prove zero physical illumination; 1D profile and 1-minute sampling remain limited.'
    }
    curve['note'] = ('已按逐分钟球面目标受光证据筛选云色时序；未证实的分钟不绘制，不代表物理上绝对无光。'
                     if profile_available else
                     '缺少可用目标光路证据；云色时序不绘制，不能以旧简化曲线推断晚霞持续时间。')
    return curve
